const K = 1010;

function powmod(a, x) {
    if (x === 0) return 1;
    if (x % 2 === 0) return powmod(a * 1n * a % BigInt(MOD), Math.floor(x / 2));
    return Number(BigInt(a) * BigInt(powmod(a, x - 1)) % BigInt(MOD));
}

const dp = Array.from({ length: K }, () => Array(K).fill(0));

const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
    let idx = 0;
    const k = input[idx++], va = input[idx++], vb = input[idx++];

    const den = powmod(va + vb, MOD - 2);
    const pa = Number(BigInt(va) * BigInt(den) % BigInt(MOD));
    const pb = Number(BigInt(vb) * BigInt(den) % BigInt(MOD));
    const one_b = Number(BigInt(pa) * BigInt(powmod(pb, MOD - 2)) % BigInt(MOD));

    for (let i = k - 1; i >= 0; i--) {
        for (let j = k; j >= 1; j--) {
            if (i + j >= k) {
                dp[i][j] = (i + j + one_b) % MOD;
