                dp[i][j] = Number(
                    (BigInt(pa) * BigInt(dp[i][j + 1]) +
                        BigInt(pb) * BigInt(dp[i + j][j])) %
                    BigInt(MOD)
                );
            }
        }
    }
    console.log(dp[0][1]);
}

